<?php
// Controller area telah memeriksa role. Halaman bersama bukan endpoint publik.
if(!isset($kbmHistoryAdmin)){http_response_code(404);exit;}
require_once __DIR__.'/monitoring_kbm_history.php';
$db=Database::getInstance();$ready=kbm_admin_ready($db);$data=null;$detail=null;$audits=[];$pageError='';
if(!in_array($_SERVER['REQUEST_METHOD'],['GET','POST','HEAD'],true)){http_response_code(405);exit;}
if($_SERVER['REQUEST_METHOD']==='POST') {
    if(!$kbmHistoryAdmin){http_response_code(403);exit('Akademik hanya dapat melihat riwayat.');}
    try {
        if(!is_string($_POST['csrf_token']??null)||!verify_csrf($_POST['csrf_token'])) throw new RuntimeException('Sesi keamanan berakhir. Muat ulang halaman sebelum menyimpan koreksi.');
        if(!$ready) throw new RuntimeException('Penyimpanan KBM belum tersedia.');
        if(kbm_input($_POST,'action')!=='koreksi') throw new InvalidArgumentException('Tindakan tidak tersedia.');
        kbm_history_correct($db,(int)$_SESSION['user_id'],$_POST);
        $_SESSION['kbm_history_success']='Koreksi disimpan. Laporan asli tetap utuh dan perubahan tercatat di audit.';
    } catch(PDOException $e) {error_log('Koreksi riwayat KBM: '.$e->getMessage());$_SESSION['kbm_history_error']='Koreksi tidak tersimpan. Periksa data terbaru lalu coba kembali.';}
    catch(InvalidArgumentException|RuntimeException $e) {$_SESSION['kbm_history_error']=$e->getMessage();}
    $return=[];foreach(['tanggal_mulai','tanggal_selesai','sesi','kelas','guru','status','halaman','per_halaman','detail_jadwal','detail_tanggal'] as $key) if(is_string($_GET[$key]??null)) $return[$key]=$_GET[$key];
    redirect('riwayat_kbm.php?'.http_build_query($return));
}
if($ready) {
    try {
        $data=kbm_history_page($db,$_GET);
        if(isset($_GET['detail_jadwal'])||isset($_GET['detail_tanggal'])) {
            $id=kbm_int($_GET,'detail_jadwal');$date=kbm_input($_GET,'detail_tanggal');
            $detail=kbm_history_row($db,$id,$date);
            if(!$detail) throw new InvalidArgumentException('Catatan yang dipilih tidak ditemukan.');
            if($detail['pertemuan_id']!==null) $audits=kbm_history_audit($db,(int)$detail['pertemuan_id']);
        }
    } catch(InvalidArgumentException $e) {http_response_code(400);$pageError=$e->getMessage();}
    catch(Throwable $e) {error_log('Riwayat KBM: '.$e->getMessage());http_response_code(503);$pageError='Riwayat belum dapat dimuat. Silakan coba lagi.';}
}
$success=$_SESSION['kbm_history_success']??'';$error=$_SESSION['kbm_history_error']??'';unset($_SESSION['kbm_history_success'],$_SESSION['kbm_history_error']);
function kbm_hh(mixed $v): string {return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function kbm_history_date_label(string $date): string {
    $d=kbm_date($date);$days=[1=>'Senin','Selasa','Rabu','Kamis','Jumat','Sabtu','Minggu'];$months=[1=>'Januari','Februari','Maret','April','Mei','Juni','Juli','Agustus','September','Oktober','November','Desember'];
    return $days[(int)$d->format('N')].', '.$d->format('j').' '.$months[(int)$d->format('n')].' '.$d->format('Y');
}
function kbm_history_time(?string $value): string {return $value===null?'Belum tercatat':$value.' WIB';}
function kbm_history_url(array $changes): string {global $data;return 'riwayat_kbm.php?'.http_build_query(array_merge($data['filters'],$changes));}
function kbm_history_select(string $key,string $label,array $options): void {
    global $data;$selected=$data['filters'][$key];
    echo '<div class="col-sm-6 col-xl-3"><label class="form-label" for="h_'.kbm_hh($key).'">'.kbm_hh($label).'</label><select id="h_'.kbm_hh($key).'" class="form-select" name="'.kbm_hh($key).'">';
    foreach($options as $value=>$text) echo '<option value="'.kbm_hh($value).'" '.((string)$value===$selected?'selected':'').'>'.kbm_hh($text).'</option>';
    echo '</select></div>';
}
require_once __DIR__.'/header.php';require_once __DIR__.'/sidebar.php';
?>
