<?php kbm_history_select('guru','Guru',[''=>'Semua guru']+array_column($data['teachers'],'nama','id'));kbm_history_select('status','Status',[''=>'Semua status','guru_tidak_masuk'=>'Guru tidak masuk (laporan ketua kelas)','tanpa_checkin'=>'Tidak tercatat check-in','checkin'=>'Sudah check-in / belum check-out','selesai'=>'KBM selesai','belum_checkin'=>'Guru belum check-in','belum_mulai'=>'Belum waktunya KBM','dikoreksi'=>'Hasil koreksi admin','dibatalkan'=>'Dibatalkan oleh ketua kelas']);kbm_history_select('per_halaman','Baris per halaman',['10'=>'10','25'=>'25','50'=>'50']); ?>
</div></details></div>
